<script lang="ts">import {createCheckboxController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";let {checked=$bindable(false),defaultChecked=false,disabled=false,label="",name,value="on",id="wui-checkbox"}=$props<{checked?:boolean;defaultChecked?:boolean;disabled?:boolean;label?:string;name?:string;value?:string;id?:string}>();const controller=createCheckboxController({id,defaultChecked:checked??defaultChecked,disabled,onCheckedChange:next=>checked=next});let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{if(checked!==state.checked)controller.store.setState({checked})});function p(kind:"root"|"control"|"hiddenInput"){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="control"?controller.getControlProps():controller.getHiddenInputProps(name,value))}</script><label {...p("root")} class="wui-checkbox"><span {...p("control")} class="wui-checkbox__control"></span><input {...p("hiddenInput")} class="wui-checkbox__hiddenInput" />{label}</label>
